function main({ fact_text, grade_text, check_text }) {
  const strip = (t) => String(t || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  const parseJSON = (t) => {
    const s = strip(t).replace(/```json|```/g, '');
    const m = s.match(/\{[\s\S]*\}/);
    if (m) { try { return JSON.parse(m[0]); } catch (e) { } }
    return {};
  };
  const fact = parseJSON(fact_text);
  const grade = parseJSON(grade_text);
  const check = parseJSON(check_text);
  const rawFacts = Array.isArray(fact.facts) ? fact.facts : [];
  const facts = rawFacts.map(f => {
    if (typeof f === 'string') return { en: f, zh: f };
    return { en: String((f && f.en) || '').trim(), zh: String((f && f.zh) || '').trim() };
  }).filter(f => f.en || f.zh);
  const sensLevel = String(check.level || 'S3').toUpperCase().trim();
  const sensAction = String(check.action || 'ok').toLowerCase().trim();
  return {
    summary: fact.summary || fact.summary_en || '（未识别主题）',
    facts_text: facts.length ? facts.map((f, i) => (i + 1) + '. ' + (f.en || f.zh)).join('\n') : '（无）',
    level: grade.level || 'B1',
    angle: grade.suggested_angle || '（无特殊角度）',
    sensitive: sensLevel + ' / ' + sensAction + ' / ' + (check.reason || ''),
    sens_level: sensLevel,
    sens_action: sensAction,
    sens_reason: check.reason || ''
  };
}

function main({ gen_result, fact_json, clean_level, clean_angle, clean_sensitive }) {
  const strip = (t) => String(t || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  const parseJSON = (t) => {
    const s = strip(t).replace(/```json|```/g, '');
    const m = s.match(/\{[\s\S]*\}/);
    if (!m) return {};
    try { return JSON.parse(m[0]); } catch (e) { return {}; }
  };
  const g = parseJSON(gen_result);
  const paras = (lv) => {
    const arr = Array.isArray(g[lv]) ? g[lv] : [];
    return arr.map(function(p){ return String(p || '').trim(); }).filter(Boolean);
  };
  const A2 = paras('A2'), B1 = paras('B1'), B2 = paras('B2');
  const wordsOf = (lv) => {
    const w = (g.words && Array.isArray(g.words[lv])) ? g.words[lv] : [];
    return w.map(function(x){ return String(x).trim(); }).filter(Boolean).join('\n');
  };
  const title = String(g.title || 'AI 分级阅读文章').replace(/^#+\s*/, '');
  const buildArticle = (lv, arr) => {
    const vocab = wordsOf(lv);
    return '# ' + title + '\n\n' + arr.join('\n\n') + (vocab ? '\n\nWords and Expressions\n' + vocab : '');
  };
  const fact = parseJSON(fact_json);
  const identity = {
    theme: fact.summary || '', angle: clean_angle || '', level: clean_level || '', sensitive: clean_sensitive || '',
    shelf: '30天', fit: '泛听/精读', provenance: (fact.sources || []).join('; ') || '用户提供素材',
    generated_at: new Date().toISOString(), model: 'deepseek-v4-pro', reviewer: '待人工审核'
  };
  const N = Math.max(A2.length, B1.length, B2.length);
  /* 段落 ↔ 事实卡绑定：fact_map 由 nodeGenAll 输出，用于段落级溯源 */
  const factList = Array.isArray(fact.facts) ? fact.facts : [];
  const fact_count = factList.length;
  let fact_map = null, unused_facts = [];
  try {
    const fm = (g && g.fact_map && typeof g.fact_map === 'object') ? g.fact_map : null;
    if (fm && fact_count > 0) {
      const norm = {};
      const lens = { A2: A2.length, B1: B1.length, B2: B2.length };
      ['A2','B1','B2'].forEach(function(k){
        const raw = Array.isArray(fm[k]) ? fm[k] : [];
        const arr = [];
        for (let i = 0; i < lens[k]; i++) {
          const ids = Array.isArray(raw[i]) ? raw[i] : [];
          const clean = ids.map(function(n){ return parseInt(n, 10); })
                           .filter(function(n){ return n >= 1 && n <= fact_count; });
          arr.push(clean.sort(function(a,b){ return a-b; }));
        }
        norm[k] = arr;
      });
      fact_map = norm;
      const used = {};
      ['A2','B1','B2'].forEach(function(k){ norm[k].forEach(function(ids){ ids.forEach(function(n){ used[n] = 1; }); }); });
      for (let i = 1; i <= fact_count; i++) { if (!used[i]) unused_facts.push(i); }
    }
  } catch (e) { fact_map = null; unused_facts = []; }
  return {
    title: title,
    article_a2: buildArticle('A2', A2),
    article_b1: buildArticle('B1', B1),
    article_b2: buildArticle('B2', B2),
    identity_json: JSON.stringify(identity, null, 2),
    summary: fact.summary || '',
    facts_json: JSON.stringify(fact.facts || [], null, 2),
    paras_a2: JSON.stringify(A2),
    paras_b1: JSON.stringify(B1),
    paras_b2: JSON.stringify(B2),
    para_count: N,
    fact_map: fact_map ? JSON.stringify(fact_map) : '',
    unused_facts: JSON.stringify(unused_facts),
    fact_count: fact_count
  };
}

function main({ a2_text, b1_text, b2_text, factcard, identity }) {
  const words = (t) => (t.match(/[A-Za-z0-9'-]+/g) || []).length;
  const sentences = (t) => (t.match(/[.!?]+/g) || []).length || 1;
  const LEN = { A2: [240, 400], B1: [280, 500], B2: [320, 600] };
  const SLEN = { A2: 12, B1: 18, B2: 25 };

  const stripAux = (t) => String(t || '')
    .replace(/[\u4e00-\u9fff\u3000-\u303f]*生词[表单]?[\s\S]*$/i, '')
    .replace(/(New Words?|Word List|Key Vocabulary|Vocabulary|Glossary|Words and Expressions|Words & Expressions)[^\n]*\n[\s\S]*$/i, '')
    .replace(/AI 辅助生成[^\n]*/g, '')
    .replace(/AI-assisted[^\n]*/gi, '');

  const validate = (level, article) => {
    const checks = [];
    const fails = [];
    const wc = words(article);
    const [lo, hi] = LEN[level] || [200, 900];
    if (wc < lo * 0.85 || wc > hi * 1.4) {
      fails.push('长度校验: 词数 ' + wc + '，超限（' + level + ' 应为 ' + lo + '-' + hi + '）');
      checks.push({ name: '长度校验', status: 'fail', detail: '词数 ' + wc });
    } else {
      checks.push({ name: '长度校验', status: wc > hi * 1.15 ? 'warn' : 'pass', detail: '词数 ' + wc });
    }
    const avg = wc / sentences(article);
    if (avg > SLEN[level]) {
      fails.push('句长校验: 平均句长 ' + avg.toFixed(1) + ' 词，超过上限 ' + SLEN[level]);
      checks.push({ name: '句长校验', status: 'fail', detail: avg.toFixed(1) + ' 词/句' });
    } else {
      checks.push({ name: '句长校验', status: 'pass', detail: avg.toFixed(1) + ' 词/句' });
    }
    const sensitive = ['分裂', '血腥', '赌博', '毒品', '色情', '种族歧视', '遇难者隐私'];
    const hits = sensitive.filter((w) => article.includes(w));
    if (hits.length) {
      fails.push('敏感排查: 命中 ' + hits.join('/'));
      checks.push({ name: '敏感排查', status: 'fail', detail: hits.join('/') });
    } else {
      checks.push({ name: '敏感排查', status: 'pass', detail: '' });
    }
    let factNums = [];
    try {
      const fc = JSON.parse(factcard || '{}');
      factNums = (JSON.stringify(fc).match(/\d[\d,.]*%?/g) || []).slice(0, 6);
    } catch (e) { }
    const missNums = factNums.filter((n) => !article.includes(n));
    if (factNums.length && missNums.length === factNums.length) {
      fails.push('事实一致性: 事实卡关键数字未出现');
      checks.push({ name: '事实一致性', status: 'fail', detail: '' });
    } else {
      checks.push({ name: '事实一致性', status: 'pass', detail: '' });
    }
    const highWords = ['incentive', 'regulation', 'supply chain', 'structural', 'institutional'];
    if (level === 'B2') {
      const has = highWords.some((w) => article.toLowerCase().includes(w));
      checks.push({ name: '分级一致性', status: has ? 'pass' : 'warn', detail: '' });
      if (!has) fails.push('分级一致性: B2 档缺少高阶表达');
    } else {
      checks.push({ name: '分级一致性', status: 'pass', detail: '' });
    }
    const body = stripAux(article);
    const chinese = (body.match(/[\u4e00-\u9fff]/g) || []).length;
    const placeholders = /(TBD|TODO|\{f\d+\}|XXX)/i.test(article);
    if (placeholders || chinese > 5) {
      fails.push('语言纯净度: ' + (placeholders ? '含占位符' : '正文含中文 ' + chinese + ' 字'));
      checks.push({ name: '语言纯净度', status: 'fail', detail: placeholders ? '占位符' : '中文字符 ' + chinese });
    } else {
      checks.push({ name: '语言纯净度', status: 'pass', detail: '' });
    }
    let idKeys = [];
    try { idKeys = Object.keys(JSON.parse(identity || '{}')); } catch (e) { }
    const need = ['theme', 'angle', 'shelf', 'fit', 'provenance'];
    const miss = need.filter((k) => !idKeys.includes(k));
    if (miss.length) {
      fails.push('身份完整性: 缺少 ' + miss.join('/'));
      checks.push({ name: '身份完整性', status: 'fail', detail: miss.join('/') });
    } else {
      checks.push({ name: '身份完整性', status: 'pass', detail: '' });
    }
    checks.push({ name: '合规署名', status: 'pass', detail: '人工审核标记由发布环节补充' });
    return {
      level: level,
      word_count: wc,
      score: checks.filter((c) => c.status === 'pass').length,
      pass: fails.length === 0,
      checks: checks,
      fail_reasons: fails
    };
  };

  const results = [validate('A2', a2_text), validate('B1', b1_text), validate('B2', b2_text)];
  const overall = {
    total_checks: 24,
    total_pass: results.reduce((s, r) => s + r.score, 0),
    all_pass: results.every((r) => r.pass),
    results: results
  };
  return {
    validation_json: JSON.stringify(overall),
    validation_pass: String(overall.all_pass),
    validation_score: overall.total_pass + '/24'
  };
}

function main({ style }) {
  const STYLES = {
    default: "Neutral, clear, natural expository prose — the platform's standard graded-reading style, without imitating a specific author.",
    hemingway: "Ernest Hemingway: short declarative sentences, few adjectives, concrete nouns and action verbs, understated emotion (iceberg theory).",
    zhuziqing: "Zhu Ziqing: lyrical, refined prose with vivid sensory imagery, gentle rhythm and delicate observation; warm and reflective.",
    ohenry: "O. Henry: warm humor, vivid characters and a surprising ironic twist at the end.",
    twain: "Mark Twain: colloquial, humorous and lightly satirical; down-to-earth language, witty observations and folksy charm.",
    murakami: "Haruki Murakami: quiet, imagistic narration with dreamlike metaphors, understated emotion and a sense of solitude.",
    luxun: "Lu Xun: sharp, incisive and critical; direct piercing language, irony and moral seriousness.",
    shakespeare: "William Shakespeare: elevated, rhetorical and lyrical; rich in imagery, metaphor and rhythm."
  };
  const key = String(style || '').toLowerCase();
  const base = STYLES[key] || STYLES.default;
  const instruction = base + " Keep all facts, names, numbers and the required structure (title, paragraphs, glossary) unchanged — only the writing style differs. Adapt sentence length and vocabulary to the target CEFR level.";
  return { style_key: (key in STYLES) ? key : 'default', style_instruction: instruction };
}

